import android.os.IBinder;
import android.graphics.Rect;
import android.view.Surface;
import java.lang.reflect.*;
import java.util.*;
/** Local SurfaceView children backed by real owned HWUI/Wayland Surface queues. */
public final class SdSurfaceViews {
 private static boolean installed;private static long nextSession=1;
 private static final HashMap<Long,HashSet<Long>> sessions=new HashMap<Long,HashSet<Long>>();
 private static final LinkedHashMap<Long,Node> nodes=new LinkedHashMap<Long,Node>();
 private static final Method transaction;private static final Field layers,frame,z,visible,nativeObject;
 private static final Method setSurface;
 private static final class Node {long id,parent,session;int width,height,depth,handles=1;float x,y;boolean shown,color,removed,painted;int paintedWidth,paintedHeight;float[] paintedRgb;float[] rgb={0,0,0};Node(long value){id=value;}}
 static {try{transaction=SdSurfaceControls.class.getDeclaredMethod("transaction",long.class);transaction.setAccessible(true);layers=SdSurfaceStore.class.getDeclaredField("layers");layers.setAccessible(true);Class<?> layer=Class.forName("SdSurfaceStore$Layer");frame=layer.getDeclaredField("frame");z=layer.getDeclaredField("z");visible=layer.getDeclaredField("visible");for(Field f:new Field[]{frame,z,visible})f.setAccessible(true);nativeObject=Surface.class.getDeclaredField("mNativeObject");nativeObject.setAccessible(true);setSurface=Surface.class.getDeclaredMethod("setNativeObjectLocked",long.class);setSurface.setAccessible(true);}catch(Exception error){throw new ExceptionInInitializerError(error);}}
 private static native void nativeRetire(int id);
 public static void retireLayer(long id){if(id<=0||id>Integer.MAX_VALUE)throw new IllegalArgumentException("Invalid owned layer ID");nativeRetire((int)id);}
 private static native void nativeInstall();private static native void nativeColor(Surface surface,long id,float red,float green,float blue);private static native long nativeFrames(Surface surface);
 private static final HashMap<Long,ArrayList<Barrier>> barriers=new HashMap<Long,ArrayList<Barrier>>();
 private static final ArrayDeque<Pending> pending=new ArrayDeque<Pending>();private static android.os.Handler frameQueue;
 private static final class Barrier {long surface,frame;Barrier(long s,long f){surface=SdWindowHost.nativeHardwareRetain(s);frame=f;}void close(){SdWindowHost.nativeHardwareRelease(surface);}}
 private static final class Pending {ArrayList<Runnable> operations;ArrayList<Barrier> waits;long started=android.os.SystemClock.uptimeMillis();boolean logged;Pending(ArrayList<Runnable> o,ArrayList<Barrier> w){operations=o;waits=w;}}
 private static long frames(long pointer){Surface surface=new Surface();try{setSurface.invoke(surface,SdWindowHost.nativeHardwareRetain(pointer));return nativeFrames(surface);}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}finally{surface.release();}}
 public static long nextFrame(long surface){if(!SdWindowHost.hardware())return SdSurfaceStore.nextFrame(surface);long frames=frames(surface);if(frames<0)throw new IllegalArgumentException("Frame counter needs an owned HWUI Surface");return frames+1;}
 public static synchronized void defer(long t,long id,long surface,long frameNumber){bounds(id);if(frameNumber<=0)return;long frames=frames(surface);if(frames<0)throw new IllegalArgumentException("Frame barrier needs an owned HWUI Surface");if(frames>=frameNumber)return;ArrayList<Barrier> list=barriers.get(t);if(list==null){list=new ArrayList<Barrier>();barriers.put(t,list);}list.add(new Barrier(surface,frameNumber));System.err.println("SDSURFACEVIEW=frame_deferred|control="+id+"|target="+frameNumber+"|submitted="+frames);}
 @SuppressWarnings("unchecked") public static void apply(long t,boolean synchronous){ArrayList<Runnable> operations;synchronized(SdSurfaceControls.class){try{ArrayList<Runnable> original=(ArrayList<Runnable>)transaction.invoke(null,t);operations=new ArrayList<Runnable>(original);original.clear();}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}}synchronized(SdSurfaceViews.class){ArrayList<Barrier> waits=barriers.remove(t);if(waits==null)waits=new ArrayList<Barrier>();pending.add(new Pending(operations,waits));drain();}}
 private static void drain(){while(!pending.isEmpty()){Pending first=pending.peek();boolean ready=true;for(Barrier wait:first.waits)if(frames(wait.surface)<wait.frame)ready=false;if(!ready){if(!first.logged&&android.os.SystemClock.uptimeMillis()-first.started>2000){first.logged=true;System.err.println("SDSURFACEVIEW=frame_waiting|barriers="+first.waits.size());}if(frameQueue==null)frameQueue=new android.os.Handler(android.os.Looper.getMainLooper());frameQueue.removeCallbacks(pollFrames);frameQueue.postDelayed(pollFrames,2);return;}pending.remove();for(Barrier wait:first.waits)wait.close();for(Runnable operation:first.operations)operation.run();SdSurfaceStore.transactionComplete();if(!first.waits.isEmpty())System.err.println("SDSURFACEVIEW=frame_applied|barriers="+first.waits.size());}}
 private static final Runnable pollFrames=()->{synchronized(SdSurfaceViews.class){drain();}};
 public static void merge(long target,long source){if(target==source)return;SdSurfaceControls.merge(target,source);synchronized(SdSurfaceViews.class){ArrayList<Barrier> from=barriers.remove(source);if(from!=null){ArrayList<Barrier> to=barriers.get(target);if(to==null){to=new ArrayList<Barrier>();barriers.put(target,to);}to.addAll(from);}}}
 public static synchronized void free(long t){ArrayList<Barrier> waits=barriers.remove(t);if(waits!=null)for(Barrier wait:waits)wait.close();SdSurfaceControls.freeTransaction(t);}

 public static synchronized void install(){if(installed)return;nativeInstall();installed=true;}
 public static synchronized long session(){long id=nextSession++;sessions.put(id,new HashSet<Long>());System.err.println("SDSURFACEVIEW=session_created|id="+id+"|backend=local-wayland");return id;}
 public static synchronized void sessionRelease(long id,boolean kill){HashSet<Long> children=sessions.remove(id);if(children==null)return;if(kill)for(long child:new HashSet<Long>(children))remove(child);}
 @SuppressWarnings("unchecked") private static Object layer(long id){try{Object value=((Map<Long,Object>)layers.get(null)).get(id);if(value==null)throw new IllegalArgumentException("Unknown local SurfaceControl "+id);return value;}catch(IllegalAccessException error){throw new IllegalStateException(error);}}
 private static Rect bounds(long id){if(id==0)return new Rect(0,0,SdDisplayShim.WIDTH,SdDisplayShim.HEIGHT);try{return new Rect((Rect)frame.get(layer(id)));}catch(IllegalAccessException error){throw new IllegalStateException(error);}}
 private static int depth(long id){if(id==0)return 0;try{return z.getInt(layer(id));}catch(IllegalAccessException error){throw new IllegalStateException(error);}}
 private static boolean shown(long id){if(id==0)return true;try{return visible.getBoolean(layer(id));}catch(IllegalAccessException error){throw new IllegalStateException(error);}}
 @SuppressWarnings("unchecked") private static void queue(long id,Runnable operation){synchronized(SdSurfaceControls.class){try{((ArrayList<Runnable>)transaction.invoke(null,id)).add(operation);}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}}}
 public static synchronized long create(long session,String name,int width,int height,int format,int flags,long parent){
  if(!sessions.containsKey(session))throw new IllegalArgumentException("Unknown local Surface session");if((flags&0x80)!=0)throw new UnsupportedOperationException("Protected SurfaceView is unavailable");if(width<0||height<0||width>8192||height>8192)throw new IllegalArgumentException("Invalid SurfaceView extent");if(!SdWindowHost.hardware())throw new UnsupportedOperationException("SurfaceView requires real HWUI queues");Rect extent=bounds(parent);Node node=new Node(SdSurfaceStore.create());node.parent=parent;node.session=session;node.width=width==0?Math.max(1,extent.width()):width;node.height=height==0?Math.max(1,extent.height()):height;node.shown=(flags&4)==0;node.color=(flags&0xF0000)==0x20000;nodes.put(node.id,node);sessions.get(session).add(node.id);SdSurfaceStore.retain(node.id);if(parent!=0)SdSurfaceStore.retain(parent);sync(node);if(node.color)paint(node);System.err.println("SDSURFACEVIEW=created|id="+node.id+"|parent="+parent+"|size="+node.width+"x"+node.height+"|color="+node.color+"|name="+name);return node.id;
 }
 private static void sync(Node node){if(node.removed)return;Rect parent=bounds(node.parent);int left=parent.left+Math.round(node.x),top=parent.top+Math.round(node.y);SdSurfaceStore.layout(node.id,new Rect(left,top,left+node.width,top+node.height),node.shown&&shown(node.parent));long value=(long)depth(node.parent)+node.depth;SdSurfaceStore.z(node.id,(int)Math.max(Integer.MIN_VALUE,Math.min(Integer.MAX_VALUE,value)));}
 private static void descendants(long id){for(Node child:nodes.values())if(!child.removed&&child.parent==id){sync(child);if(child.color)paint(child);descendants(child.id);}}
 private static void paint(Node node){
  if(node.removed)return;
  // Position/visibility transactions do not alter a solid layer's pixels.
  // Keep its submitted buffer and only repaint changed content or dimensions.
  if(node.painted&&node.width==node.paintedWidth&&node.height==node.paintedHeight&&Arrays.equals(node.rgb,node.paintedRgb))return;
  Surface surface=new Surface();try{setSurface.invoke(surface,SdSurfaceStore.surfaceFromControl(0,node.id));nativeColor(surface,node.id,node.rgb[0],node.rgb[1],node.rgb[2]);node.painted=true;node.paintedWidth=node.width;node.paintedHeight=node.height;node.paintedRgb=node.rgb.clone();}catch(ReflectiveOperationException error){throw new IllegalStateException(error);}finally{surface.release();}
 }
 public static void position(long t,long id,float x,float y){queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null)SdSurfaceStore.position(id,x,y);else{node.x=x;node.y=y;sync(node);}descendants(id);}});}
 public static void size(long t,long id,int width,int height){queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null)SdSurfaceStore.size(id,width,height);else{node.width=width;node.height=height;sync(node);if(node.color)paint(node);}descendants(id);}});}
 public static void layer(long t,long id,int value){queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null)SdSurfaceStore.z(id,value);else{node.depth=value;sync(node);}descendants(id);}});}
 public static void flags(long t,long id,int value,int mask){if((mask&~1)!=0)throw new UnsupportedOperationException("SurfaceView flag transition is unsupported");queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null)SdSurfaceStore.flags(id,value,mask);else{if((mask&1)!=0)node.shown=(value&1)==0;sync(node);}descendants(id);}});}
 public static void relative(long t,long id,IBinder relative,int value){long found=0;synchronized(SdSurfaceStore.class){try{for(Object key:((Map<?,?>)layers.get(null)).keySet()){long candidate=(Long)key;if(SdSurfaceStore.handle(candidate)==relative){found=candidate;break;}}}catch(IllegalAccessException error){throw new IllegalStateException(error);}}if(found==0)throw new IllegalArgumentException("Relative SurfaceControl is not owned");final long target=found;queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);long absolute=(long)depth(target)+value;int depth=(int)Math.max(Integer.MIN_VALUE,Math.min(Integer.MAX_VALUE,absolute));if(node==null)SdSurfaceStore.z(id,depth);else{node.depth=depth-depth(node.parent);sync(node);}descendants(id);}});}
 public static void color(long t,long id,float[] values){if(values==null||values.length!=3)throw new IllegalArgumentException("RGB triplet required");final float[] copy=values.clone();for(float component:copy)if(!Float.isFinite(component)||component<0||component>1)throw new IllegalArgumentException("Color outside range");queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null||!node.color)throw new IllegalArgumentException("Not a local color layer");node.rgb=copy;paint(node);}});}
 private static void forget(Node node){if(node.handles==0&&node.removed){nodes.remove(node.id);HashSet<Long> owned=sessions.get(node.session);if(owned!=null)owned.remove(node.id);}}
 private static void remove(long id){Node node=nodes.get(id);if(node==null){SdSurfaceStore.remove(id);return;}if(node.removed)return;node.removed=true;for(Node child:new ArrayList<Node>(nodes.values()))if(child.parent==id)remove(child.id);SdSurfaceStore.remove(id);if(node.parent!=0){SdSurfaceStore.release(node.parent);node.parent=0;}forget(node);System.err.println("SDSURFACEVIEW=removed|id="+id);}
 public static synchronized long copy(long id){Node node=nodes.get(id);if(node!=null)node.handles++;return SdSurfaceStore.retain(id);}
 public static synchronized void release(long id){if(id==0)return;Node node=nodes.get(id);if(node!=null){if(node.handles<=0)throw new IllegalStateException("Unbalanced SurfaceControl release");node.handles--;if(node.handles==0)remove(id);}SdSurfaceStore.release(id);if(node!=null)forget(node);}
 public static void reparent(long t,long id,long parent){queue(t,()->{synchronized(SdSurfaceViews.class){Node node=nodes.get(id);if(node==null)throw new UnsupportedOperationException("Root reparent is not supported");if(parent==0){remove(id);return;}for(long at=parent;at!=0;){if(at==id)throw new IllegalArgumentException("Surface parent cycle");Node other=nodes.get(at);at=other==null?0:other.parent;}bounds(parent);SdSurfaceStore.retain(parent);long old=node.parent;node.parent=parent;if(old!=0)SdSurfaceStore.release(old);sync(node);descendants(id);}});}
 public static synchronized void destroy(long id){remove(id);}
 public static void corner(long t,long id,float radius){if(radius!=0)throw new UnsupportedOperationException("Rounded SurfaceView crops are not supported");queue(t,()->bounds(id));}
}
